/**
 * Creates a PointsBVH closest point function that returns distance AND direction.
 *
 * This extended version is designed for constraint systems where you need
 * both the penetration depth and the push direction.
 *
 * For point clouds, the "normal" is computed as the direction from the
 * closest point to the query point (normalized).
 *
 * Uses the TSL Fn() pattern which:
 * 1. Accesses storage buffers via .element() - generates NodeBuffer_XXX.value[i] syntax
 * 2. Avoids ptr<storage, ...> in function signatures
 * 3. Works on Safari/Firefox WebGPU
 *
 * @param {StorageBufferNode} bvhIndexBuffer - Storage buffer for point indices (uint)
 * @param {StorageBufferNode} bvhPositionBuffer - Storage buffer for point positions (vec3f)
 * @param {StorageBufferNode} bvhNodeBuffer - Storage buffer for BVH nodes (flat f32 array)
 * @returns {Function} A TSL function that computes closest point with direction
 */
export function createPointsBVHClosestPointWithDirectionFn(bvhIndexBuffer: StorageBufferNode, bvhPositionBuffer: StorageBufferNode, bvhNodeBuffer: StorageBufferNode): Function;
/**
 * Computes the squared distance from a point to an AABB.
 */
export const distanceSqToBoundsWGSL: any;
